{"role":"assistant","content":[{"type":"text","text":"Now I'll create the fraud detection agent. This will be a deterministic agent (no LLM calls) that analyzes account patterns and dispute history."},{"type":"tool-call","toolCallId":"call-013","toolName":"write_file","args":{"filePath":"C:\Users\17909\WorkBuddy AI\2026-10-07-14-39-04\backend\src\modules\dispute\agents\fraud-agent.ts","content":"import type { AgentInput } from './contracts';
import { sourceIndex } from './shared';

export interface FraudSignal {
  type: 'account_risk' | 'frequency_anomaly' | 'adverse_ratio' | 'thin_history' | 'counterparty_asymmetry';
  severity: 'low' | 'medium' | 'high';
  description: string;
  sourceIndex?: number;
}

export interface FraudAssessment {
  agent: 'fraud_detection_agent';
  overallRisk: 'low' | 'medium' | 'high';
  signals: FraudSignal[];
  recommendedAction: 'proceed' | 'flag_for_review' | 'escalate';
}

export function runFraudAgent(input: AgentInput): FraudAssessment {
  const signals: FraudSignal[] = [];
  const rider = input.rider_profile;
  const driver = input.driver_profile;
  \n  // 1. Account risk flags
  if (rider.account_flags && rider.account_flags.length > 0) {
    signals.push({
      type: 'account_risk',
      severity: 'medium',
      description: `Rider account has flags: ${rider.account_flags.join(', ')}`,
      sourceIndex: sourceIndex('rider_profile.account_flags'),
    });
  }
  \n  // 2. Dispute frequency anomaly
  const riderDisputeCount = rider.past_disputes_count || 0;
  const driverDisputeCount = driver.past_disputes_count || 0;
  if (riderDisputeCount > 5) {
    signals.push({
      type: 'frequency_anomaly',
      severity: riderDisputeCount > 10 ? 'high' : 'medium',
      description: `Rider has ${riderDisputeCount} past disputes`,
      sourceIndex: sourceIndex('rider_profile.past_disputes_count'),
    });
  }
  \n  // 3. Adverse outcome ratio
  const riderAdverse = rider.adverse_outcomes_count || 0;
  if (riderAdverse > 3) {
    signals.push({
      type: 'adverse_ratio',
      severity: 'high',
      description: `Rider has ${riderAdverse} adverse outcomes`,
      sourceIndex: sourceIndex('rider_profile.adverse_outcomes_count'),
    });
  }
  \n  // 4. Thin account history
  const accountAge = rider.account_age_days || 0;
  if (accountAge < 30) {
    signals.push({
      type: 'thin_history',
      severity: 'low',
      description: `Rider account is only ${accountAge} days old`,
      sourceIndex: sourceIndex('rider_profile.account_age_days'),
    });
  }
  \n  // 5. Counterparty asymmetry
  if (riderDisputeCount > driverDisputeCount * 3) {
    signals.push({
      type: 'counterparty_asymmetry',
      severity: 'medium',
      description: `Rider disputes (${riderDisputeCount}) greatly exceed driver disputes (${driverDisputeCount})`,
      sourceIndex: sourceIndex('rider_profile.past_disputes_count'),
    });
  }
  \n  // Determine overall risk
  const highCount = signals.filter(s => s.severity === 'high').length;
  const mediumCount = signals.filter(s => s.severity === 'medium').length;
  \n  let overallRisk: FraudAssessment['overallRisk'] = 'low';
  let recommendedAction: FraudAssessment['recommendedAction'] = 'proceed';
  \n  if (highCount >= 2 || (highCount === 1 && mediumCount >= 2)) {
    overallRisk = 'high';
    recommendedAction = 'escalate';
  } else if (highCount === 1 || mediumCount >= 2) {
    overallRisk = 'medium';
    recommendedAction = 'flag_for_review';
  }
  \n  return {
    agent: 'fraud_detection_agent',
    overallRisk,
    signals,
    recommendedAction,
  };
}"}}]}

