  it('escalates on multiple high-risk signals', () => {
    const input = sampleDatasetSchema.parse({
      rider_profile: {
        past_disputes_count: 15,
        adverse_outcomes_count: 5,
        account_age_days: 10,
        account_flags: ['suspicious_activity'],
      },
      driver_profile: {
        past_disputes_count: 1,
        adverse_outcomes_count: 0,
        account_age_days: 730,
        account_flags: [],
      },
    });
    const result = runFraudAgent(input);
    expect(result.overallRisk).toBe('high');
    expect(result.recommendedAction).toBe('escalate');
    expect(result.signals.length).toBeGreaterThanOrEqual(4);
  });

  it('cites valid source indices', () => {
    const input = sampleDatasetSchema.parse({
